mapper.insert:
insert into user_quota_account (
  user_id, quota_balance, frozen_quota, used_quota, create_time, update_time
) values (
  #{userId}, 0.00, 0.00, 0.00, now(), now()
)
on duplicate key update user_id = values(user_id)

mapper.update:
update user_quota_account
set quota_balance = quota_balance - #{amount},
    used_quota = used_quota + #{amount},
    update_time = now()
where user_id = #{userId}
  and quota_balance >= #{amount}

mapper.insert:
insert into user_quota_flow (
  flow_id, user_id, flow_type, biz_id, quota_amount, before_balance, after_balance, remark, create_time
) values (
  #{flowId}, #{userId}, #{flowType}, #{bizId}, #{quotaAmount}, #{beforeBalance}, #{afterBalance}, #{remark}, #{createTime}
)

mapper.select:
select flow_id, user_id, flow_type, biz_id, quota_amount, before_balance, after_balance, remark, create_time
from user_quota_flow
where user_id = #{userId}
  and flow_type = #{flowType}
  and biz_id = #{bizId}
limit 1

select flow_id, user_id, flow_type, biz_id, quota_amount, before_balance, after_balance, remark, create_time
from user_quota_flow
where user_id = #{userId}
order by create_time desc, flow_id desc
limit #{limit}

